(window.VADE_TASKS=window.VADE_TASKS||{})["L015"]={"id": "L015", "domain": "law", "released": true, "group": "Consumer Product Safety", "category": "Draft", "title": "Negotiation-ready voluntary recall plan", "question": "Using only the supplied public authorities and stipulated matter materials, as of September 16, 2026 at 5:00 p.m. Eastern Time, draft one integrated, negotiation-ready post-report voluntary corrective-action-plan term sheet and recall-execution protocol for the Aurora SolaraGo ET-220 matter. Keep the analysis downstream of Aurora's completed Section 15(b) report and ground the instrument in the correct authority hierarchy and the closed-record product, hazard, population, and operational facts. Make the instrument operationally executable by coherently connecting the recall scope and remedy to notice, channel and logistics controls, responsible owners, monitoring, effectiveness measures, and escalation. Clearly distinguish operative commitments from Aurora proposals and unresolved staff-dependent terms, preserve the voluntary CAP's legal-status and acceptance boundaries, and do not imply CPSC approval, release, or closure.", "cutoff": "2026-09-16T17:00:00-04:00", "core_conclusion": "The required work product is one integrated, negotiation-ready post-report voluntary CAP term sheet and recall-execution protocol for Aurora's stipulated ET-220 matter. It must use 16 CFR § 1115.20 as controlling law and the visibly Revised August, 2021 Recall Handbook only as subordinate staff guidance; reconcile one 82,400-unit affected population without double counting returns; connect product, hazard, remedy, notice, channel, logistics, owner, budget, monitoring, effectiveness, and escalation provisions; preserve contact-population overlap and operational constraints; and state all unresolved staff-dependent terms conditionally. Aurora's positions and targets are proposals rather than legal sufficiency or staff agreement, staff negotiation is not Commission action, and no CAP is effective until final Commission acceptance.", "atoms": [{"label": "CAP authority classification, Handbook hierarchy, post-report scope, legal-effect classification, and reserved-action posture", "expected": "Treat 16 CFR § 1115.20 as controlling and the Recall Handbook as subordinate CPSC staff guidance. Confine the work to the proposed post-report CAP and execution protocol; do not analyze Aurora's completed Section 15(b) reporting decision. Describe the CAP as a voluntary instrument that has no legally binding effect under § 1115.20(a), becomes effective only upon final Commission acceptance, and does not restrict the Commission from seeking broader action if new facts arise or the plan is insufficient.", "unit": null, "tolerance": null, "fatal": true, "evidence": [1, 15, 16, 17]}, {"label": "Covered product identifiers, date and serial scope, affected population, distribution-level locations, alleged cause and hazard, incident and injury types, and interim handling instructions", "expected": "Define the covered product as every SolaraGo rechargeable camp lantern model ET-220 in matte black or blaze orange, SKUs ET220-BLK and ET220-ORG, UPCs 790000022011 and 790000022028, date codes 26015-26183, and serial format ET22-YYDDD-NNNNN. Use the interior battery-door label and supporting photographs, not exterior silhouette alone, to distinguish ET-220 from ET-210 and ET-221. Cover all 82,400 units because the component-lot map cannot support a narrower finished-unit subset: 3,100 never distributed and 79,300 distributed. Reconcile the cutoff locations as 2,080 at TrailHub, 1,140 at CampSquare, 640 at independent retailers, 400 at MarketSquare, 1,240 returned units, and an estimated 73,800 with consumers or otherwise outside confirmed channel inventory; the returned units remain within the distributed population. State the alleged mechanism as an internal battery-pack weld burr abrading a separator after ordinary drops or vibration, with possible internal shorting, overheating, smoke, ignition, fire, and burns. State the closed-record incident profile—17 overheating or smoke incidents, five open-flame events, three property-damage reports, two first-degree burns, and no death or hospitalization—without deciding substantial-product-hazard status. Pending remedy instructions, direct owners to stop using and charging the lantern, disconnect it, and keep it away from combustibles; visibly compromised units must not be consumer-mailed or transported and require local pickup.", "unit": null, "tolerance": null, "fatal": true, "evidence": [2, 4, 5, 6, 18]}, {"label": "Refund and replacement options, repair exclusion, replacement validation materials, recurrence-prevention measures, subject-firm signatures, Commission-publicity agreement, and additional negotiated terms", "expected": "Present Aurora's proposed consumer election as either a full $69.99 refund or a no-cost ET-221 replacement, with no coupon, store credit, prorated refund, or consumer-installed repair. Explain that no ET-220 repair design is validated and the sealed battery pack cannot be serviced through Aurora's existing field network. Make ET-221 samples, drawings, and the September 12 accredited-laboratory report available while stating that the 120-sample protocol and replacement have not been approved by CPSC staff. Include the stopped ET-220 production and purchase orders and the proposed ET-221 weld inspection, lot-to-serial traceability, supplier audit, and drop-and-vibration sampling controls, while leaving long-term audit frequency and supplier-remediation milestones open for negotiation. Provide authorized Aurora representative signature blocks, agreement to the regulation's limited Commission-publicity term, and matter-appropriate attachment or additional-agreement placeholders without inventing an individual signatory or an agreement on unresolved staff-dependent items.", "unit": null, "tolerance": null, "fatal": true, "evidence": [7, 8, 10, 12, 13]}, {"label": "Eligibility and fulfillment mechanics, replacement supply, refund timing, distribution-chain timetable, stop-sale status, return transport, quarantine, custody tracking, disposition, verification, and reentry controls", "expected": "Permit eligibility verification through a photograph of the model label and legible serial number without requiring a receipt; route illegible-label cases to contextual photographic review and disputed cases to the program manager. State the proposed service goal of remedy dispatch within ten business days after verification, with electronic refunds within three business days, checks within seven business days, replacement shipping capacity of 4,000 units per business day, 8,000 ET-221 units available September 30, and 12,000 additional units per week beginning October 5. Preserve the September 4 stop-sale and inventory hold, national-retailer and marketplace blocks, tested non-overridable SKU controls, and follow-up and escalation for the four independent retailers representing an estimated 118 units that have not acknowledged. Coordinate standard ground-return kits, special pickup in Alaska, Hawaii, and for visibly compromised units, Red Pine's serial-level custody records and quarantine, and the existing segregation of 3,100 warehouse units and 1,240 returns. State Aurora's proposed destruction and materials recovery through ClearCycle, exclude rework, resale, donation, liquidation, and return to the foreign manufacturer, and require reconciliations and certificates. Destruction scheduling and CPSC verification or witnessing must remain conditional because no method or verification arrangement has been approved.", "unit": null, "tolerance": null, "fatal": true, "evidence": [7, 9, 19, 21, 22, 27, 31]}, {"label": "Notice methods, recipient classes, notice attachments, direct and partner-held contact populations, privacy constraints, communications channels, hotline resources, and unresolved launch terms", "expected": "Create an integrated English-and-Spanish notice program for CPSC staff review covering email, postal mail, consented text messages, the reserved recall website and toll-free number, retailer and marketplace messages, in-store notices, press, social media, paid search, and other targeted channels. Use Aurora's 25,600 direct orders, including 24,980 deliverable emails, 25,310 postal addresses, and only the 18,200 mobile numbers with recorded text consent under the stipulated internal rule; also use the 6,660 registrations not matched to direct orders while accounting for failed address checks. Require CampSquare to contact its 8,400 SKU-specific purchasers, MarketSquare to message its 11,900 transaction accounts, and TrailHub to use its 13,900 imprecise loyalty contacts with wording that does not represent them as confirmed purchasers. Do not sum these groups into a unique-consumer total because cross-channel overlap is unresolved. Keep partner data within partner systems, limit vendor fields and uses, log disclosures, and apply the stipulated return-or-deletion restriction. Activate the bilingual hotline capacity and record identifiers, remedy elections, special handling, failed deliveries, incidents, and escalations. Attach or identify the required notice drafts, but leave final wording, paid-media allocation, outreach beyond available populations, launch sequence, and the proposed September 25 target conditional on operational readiness and staff review.", "unit": null, "tolerance": null, "fatal": true, "evidence": [3, 19, 20, 24, 25]}, {"label": "Implementation steps, Aurora owner roles, vendor roles, training, budget authority, timetable ownership, inventory controls, and escalation ownership", "expected": "Assign the Vice President of Quality as program executive, Product Safety Director as day-to-day manager, General Counsel as CPSC liaison, Supply Chain Director as channel and inventory owner, Customer Experience Director as hotline and remedy owner, Data Protection Officer as contact-data owner, and Controller as budget and payment owner. Place Red Pine, ClearCycle, the communications vendor, and the customer-care vendor under the corresponding Aurora owner and prohibit vendor changes to scope, remedy, messages, or disposition without written Aurora approval. Convert each channel, notice, remedy, return, quarantine, disposition, incident-intake, privacy, payment, reporting, and escalation step into written procedures with named handoffs and timetables. Require the 12-person command team, role-specific training within 48 hours after procedures and scripts are frozen, completion records, and first-month weekly refreshers. Treat the $11.2 million reserve and its category allocations as planning controls rather than a cap on later authorized safety action; apply the Controller's $500,000 reallocation limit and CFO approval above it. Preserve non-overridable SKU blocks, exception reports, marked access-controlled quarantine, and serial-level release rejection.", "unit": null, "tolerance": null, "fatal": true, "evidence": [9, 21, 22, 30, 31]}, {"label": "Commission-monitoring acknowledgment, customer-list and necessary-information commitment, internal and CPSC report cadence, report fields, effectiveness targets, escalation triggers, disposition verification, cease-monitoring request, and continuing obligations", "expected": "Acknowledge Commission monitoring and commit Aurora to furnish necessary information, including a securely transmitted customer-list export with field definitions, source, match logic, and duplicate limitations when requested. Use daily internal dashboards for the first 30 days, weekly executive reviews for the first 90 days, and monthly data freezes, while identifying monthly CPSC reporting as Aurora's unaccepted proposal rather than an agreed cadence. Report affected and channel-unit status; acknowledgments and exceptions; unique contacts attempted and delivered by channel; hotline and web activity; claims, approvals, escalations, refunds, replacements, returns, quarantine, custody variances, disposition certificates, post-announcement incidents, injuries and property damage; and spending. Preserve the management targets for channel acknowledgment, 99 percent channel-inventory reconciliation within seven days, 90 percent delivery across usable direct email and postal records within 14 days, remedy dispatch within ten business days, zero unauthorized post-hold sales, and no more than one percent monthly custody variance, without characterizing them as legally sufficient or staff-approved. Include the stipulated same-day and one-business-day escalation triggers and leave the CPSC-notification protocol for escalated events open for negotiation. Coordinate destruction verification in advance. Any cessation posture must be an updated-report request for CPSC consideration, not unilateral closure, and continuing recall implementation must remain intact.", "unit": null, "tolerance": null, "fatal": true, "evidence": [1, 11, 23, 26, 27, 28, 29]}, {"label": "Optional non-admission election, permitted clause substance, proposed-plan status, final-acceptance condition, unresolved wording, and operative-commitment consistency", "expected": "Include Aurora's requested § 1115.20(a)(1)(xiii) non-admission statement or equivalent as a proposed negotiating term, while recording that staff has neither accepted nor rejected it and final wording remains unresolved. Do not make remedy performance, monitoring, information furnishing, or other execution commitments conditional on that request. State separately that no CAP has been signed, approved, or finally accepted as of the September 16 cutoff; a staff-negotiated draft is not a Commission decision; and the CAP becomes effective only upon final Commission acceptance. Do not imply a release, closure, guaranteed acceptance, or restriction on later Commission action.", "unit": null, "tolerance": null, "fatal": true, "evidence": [1, 14, 15]}], "requirements": [{"atom": "CAP authority classification, Handbook hierarchy, post-report scope, legal-effect classification, and reserved-action posture", "criterion": "Treat 16 CFR § 1115.20 as controlling and the visibly Revised August 2021 Recall Handbook as subordinate CPSC staff guidance. Keep the work downstream of the completed Section 15(b) report. Correctly state the CAP's voluntary and nonbinding status, its dependence on final Commission acceptance, and the Commission's preserved authority to seek broader action.", "fatal": true}, {"atom": "Covered product identifiers, date and serial scope, affected population, distribution-level locations, alleged cause and hazard, incident and injury types, and interim handling instructions", "criterion": "Correctly define the covered ET-220 identifiers and full 82,400-unit scope because component lots cannot support a narrower finished-unit subset. Reconcile 79,300 distributed and 3,100 never-distributed units, including 4,260 confirmed channel units, 1,240 returned units within the distributed population, and 73,800 estimated outside confirmed channel inventory. Preserve the alleged mechanism, closed-record incident profile, product-identification method, and interim handling instructions without deciding substantial-product-hazard status.", "fatal": true}, {"atom": "Refund and replacement options, repair exclusion, replacement validation materials, recurrence-prevention measures, subject-firm signatures, Commission-publicity agreement, and additional negotiated terms", "criterion": "Provide Aurora's proposed election between a full $69.99 refund and a no-cost ET-221 replacement, excluding repair and lesser-value remedies. Address validation materials and recurrence controls without implying staff approval; preserve open audit and supplier-remediation terms; and include the required signature, limited publicity, and additional-negotiated-term formalities without inventing agreement or an individual signatory.", "fatal": true}, {"atom": "Eligibility and fulfillment mechanics, replacement supply, refund timing, distribution-chain timetable, stop-sale status, return transport, quarantine, custody tracking, disposition, verification, and reentry controls", "criterion": "Supply executable eligibility, escalation, refund, replacement-capacity, stop-sale, retailer-follow-up, return, special-pickup, quarantine, custody, segregation, destruction, reconciliation, certification, and reentry-prevention terms. Preserve the stipulated timing and capacity constraints, and leave destruction scheduling and CPSC verification or witnessing conditional because no arrangement has been approved.", "fatal": true}, {"atom": "Notice methods, recipient classes, notice attachments, direct and partner-held contact populations, privacy constraints, communications channels, hotline resources, and unresolved launch terms", "criterion": "Create an integrated bilingual notice program using the stipulated direct, registration, retailer, marketplace, web, hotline, in-store, press, social, paid-search, and targeted channels. Preserve the supplied population counts, consent and precision limits, partner-system and vendor-data restrictions, and hotline intake requirements. Do not sum unresolved overlapping contact populations, and keep final wording, paid-media allocation, expanded outreach, and launch sequencing conditional on operational readiness and staff review.", "fatal": true}, {"atom": "Implementation steps, Aurora owner roles, vendor roles, training, budget authority, timetable ownership, inventory controls, and escalation ownership", "criterion": "Assign the seven stipulated Aurora functional owners and corresponding vendors, retain Aurora approval control over vendor changes, and connect written procedures, handoffs, timetables, training, budget controls, inventory safeguards, and escalation ownership. Treat the $11.2 million reserve as a planning control rather than a cap on later authorized safety action.", "fatal": true}, {"atom": "Commission-monitoring acknowledgment, customer-list and necessary-information commitment, internal and CPSC report cadence, report fields, effectiveness targets, escalation triggers, disposition verification, cease-monitoring request, and continuing obligations", "criterion": "Acknowledge Commission monitoring and Aurora's necessary-information obligations, including a secure customer-list export with documented fields, sources, matching logic, and duplicate limitations. Provide the stipulated internal cadence, proposed external cadence, report fields, management targets, escalation triggers, and advance disposition-verification process without portraying proposals or targets as approved or legally sufficient. Any cessation posture must be a request for CPSC consideration, with continuing recall execution preserved.", "fatal": true}, {"atom": "Optional non-admission election, permitted clause substance, proposed-plan status, final-acceptance condition, unresolved wording, and operative-commitment consistency", "criterion": "Present Aurora's optional non-admission request as an unresolved proposed term and do not condition remedy, monitoring, information-furnishing, or execution commitments on it. State that no CAP has been signed, approved, or finally accepted at the cutoff, staff negotiation is not Commission action, and effectiveness requires final Commission acceptance. Do not imply release, closure, guaranteed acceptance, or limits on later Commission action.", "fatal": true}], "evidence": [{"source_id": "S1", "quote": "A corrective action plan is a document, signed by a subject firm, which sets forth the remedial action which the firm will voluntarily undertake to protect the public, but which has no legally binding effect. The Commission reserves the right to seek broader corrective action if it becomes aware of new facts or if the corrective action plan does not sufficiently protect the public.", "locator": "16 CFR § 1115.20(a)", "note": "A voluntary CAP has no legally binding effect, and the Commission retains authority to seek broader corrective action if new facts arise or the plan is insufficient.", "link": "https://www.ecfr.gov/current/title-16/chapter-II/subchapter-B/part-1115#:~:text=A%20corrective%20action%20plan%20is%20a%20document%2C%20signed%20by%20a,does%20not%20sufficiently%20protect%20the%20public", "link_method": "text", "n": 1}, {"source_id": "S1", "quote": "A statement of the nature of the alleged hazard associated with the product, including the nature of the alleged defect or noncompliance and type(s) of injury or potential injury presented.", "locator": "16 CFR § 1115.20(a)(1)(i)", "note": "As appropriate, a CAP includes the alleged hazard, alleged defect or noncompliance, and actual or potential injury types.", "link": "https://www.ecfr.gov/current/title-16/chapter-II/subchapter-B/part-1115#:~:text=A%20statement%20of%20the%20nature%20of%20the%20alleged%20hazard%20associated,of%20injury%20or%20potential%20injury%20presented", "link_method": "text", "n": 2}, {"source_id": "S1", "quote": "A detailed statement of the means to be employed to notify the public of the alleged product hazard (e.g., letter, press release, advertising), including an identification of the classes of persons who will receive such notice and a copy or copies of the notice or notices to be used.", "locator": "16 CFR § 1115.20(a)(1)(ii)", "note": "As appropriate, a CAP identifies public-notice methods, recipient classes, and the notice materials to be used.", "link": "https://www.ecfr.gov/current/title-16/chapter-II/subchapter-B/part-1115#:~:text=A%20detailed%20statement%20of%20the%20means%20to%20be%20employed%20to,notice%20or%20notices%20to%20be%20used", "link_method": "text", "n": 3}, {"source_id": "S1", "quote": "A specification of model number and/or other appropriate descriptions of the product.", "locator": "16 CFR § 1115.20(a)(1)(iii)", "note": "As appropriate, a CAP specifies the product by model number or other suitable descriptions.", "link": "https://www.ecfr.gov/current/title-16/chapter-II/subchapter-B/part-1115#:~:text=A%20specification%20of%20model%20number%20and%2For%20other%20appropriate%20descriptions%20of%20the%20product", "link_method": "text", "n": 4}, {"source_id": "S1", "quote": "Any necessary instructions regarding use or handling of the product pending correction.", "locator": "16 CFR § 1115.20(a)(1)(iv)", "note": "As appropriate, a CAP provides necessary interim use or handling instructions.", "link": "https://www.ecfr.gov/current/title-16/chapter-II/subchapter-B/part-1115#:~:text=Any%20necessary%20instructions%20regarding%20use%20or%20handling%20of%20the%20product%20pending%20correction", "link_method": "text", "n": 5}, {"source_id": "S1", "quote": "An explanation of the specific cause of the alleged substantial product hazard, if known.", "locator": "16 CFR § 1115.20(a)(1)(v)", "note": "As appropriate, a CAP explains the specific cause of the alleged hazard when known.", "link": "https://www.ecfr.gov/current/title-16/chapter-II/subchapter-B/part-1115#:~:text=An%20explanation%20of%20the%20specific%20cause%20of%20the%20alleged%20substantial,product%20hazard%2C%20if%20known", "link_method": "text", "n": 6}, {"source_id": "S1", "quote": "The firm should indicate whether it is repairing or replacing the product or refunding its purchase price. If products are to be returned to a subject firm, the corrective action plan should indicate their disposition (e.g., reworked, destroyed, returned to foreign manufacturer). Samples of replacement products and relevant drawings and test data for repairs or replacements should be available.", "locator": "16 CFR § 1115.20(a)(1)(vi)", "note": "A CAP identifies the remedy, returned-product disposition, and availability of samples, drawings, and testing materials for a repair or replacement.", "link": "https://www.ecfr.gov/current/title-16/chapter-II/subchapter-B/part-1115#:~:text=The%20firm%20should%20indicate%20whether%20it%20is%20repairing%20or%20replacing,repairs%20or%20replacements%20should%20be%20available", "link_method": "text", "n": 7}, {"source_id": "S1", "quote": "A statement of the steps that will be, or have been, taken to reasonably prevent recurrence of the alleged substantial product hazard in the future.", "locator": "16 CFR § 1115.20(a)(1)(vii)", "note": "As appropriate, a CAP states completed or planned recurrence-prevention measures.", "link": "https://www.ecfr.gov/current/title-16/chapter-II/subchapter-B/part-1115#:~:text=A%20statement%20of%20the%20steps%20that%20will%20be%2C%20or%20have,substantial%20product%20hazard%20in%20the%20future", "link_method": "text", "n": 8}, {"source_id": "S1", "quote": "A statement of the action which will be undertaken to correct product units in the distribution chain, including a timetable and specific information about the number and location of such units.", "locator": "16 CFR § 1115.20(a)(1)(viii)", "note": "As appropriate, a CAP specifies distribution-chain corrective actions, a timetable, and unit numbers and locations.", "link": "https://www.ecfr.gov/current/title-16/chapter-II/subchapter-B/part-1115#:~:text=A%20statement%20of%20the%20action%20which%20will%20be%20undertaken%20to,number%20and%20location%20of%20such%20units", "link_method": "text", "n": 9}, {"source_id": "S1", "quote": "The signatures of representatives of the subject firm.", "locator": "16 CFR § 1115.20(a)(1)(ix)", "note": "As appropriate, a CAP contains subject-firm representative signatures.", "link": "https://www.ecfr.gov/current/title-16/chapter-II/subchapter-B/part-1115#:~:text=The%20signatures%20of%20representatives%20of%20the%20subject%20firm", "link_method": "text", "n": 10}, {"source_id": "S1", "quote": "An acknowledgment by the subject firm that the Commission may monitor the corrective action and that the firm will furnish necessary information, including customer lists.", "locator": "16 CFR § 1115.20(a)(1)(x)", "note": "As appropriate, a CAP acknowledges Commission monitoring and commits the firm to furnish necessary information, including customer lists.", "link": "https://www.ecfr.gov/current/title-16/chapter-II/subchapter-B/part-1115#:~:text=An%20acknowledgment%20by%20the%20subject%20firm%20that%20the%20Commission%20may,furnish%20necessary%20information%2C%20including%20customer%20lists", "link_method": "text", "n": 11}, {"source_id": "S1", "quote": "An agreement that the Commission may publicize the terms of the plan to the extent necessary to inform the public of the nature and extent of the alleged substantial product hazard and of the actions being undertaken to correct the alleged hazard presented.", "locator": "16 CFR § 1115.20(a)(1)(xi)", "note": "As appropriate, a CAP permits Commission publicity of its terms to inform the public about the alleged hazard and corrective actions.", "link": "https://www.ecfr.gov/current/title-16/chapter-II/subchapter-B/part-1115#:~:text=An%20agreement%20that%20the%20Commission%20may%20publicize%20the%20terms%20of,to%20correct%20the%20alleged%20hazard%20presented", "link_method": "text", "n": 12}, {"source_id": "S1", "quote": "Additional points of agreement, as appropriate.", "locator": "16 CFR § 1115.20(a)(1)(xii)", "note": "A CAP may contain additional matter-appropriate points of agreement.", "link": "https://www.ecfr.gov/current/title-16/chapter-II/subchapter-B/part-1115#:~:text=Additional%20points%20of%20agreement%2C%20as%20appropriate", "link_method": "text", "n": 13}, {"source_id": "S1", "quote": "If desired by the subject firm, the following statement or its equivalent: “The submission of this corrective action plan does not constitute an admission by (the subject firm) that either reportable information or a substantial product hazard exists.”", "locator": "16 CFR § 1115.20(a)(1)(xiii)", "note": "At the subject firm's election, a CAP may contain the specified non-admission statement or equivalent language.", "link": "https://www.ecfr.gov/current/title-16/chapter-II/subchapter-B/part-1115#:~:text=If%20desired%20by%20the%20subject%20firm%2C%20the%20following%20statement%20or,or%20a%20substantial%20product%20hazard%20exists.%E2%80%9D", "link_method": "text", "n": 14}, {"source_id": "S1", "quote": "An acknowledgment that the corrective action plan becomes effective only upon its final acceptance by the Commission.", "locator": "16 CFR § 1115.20(a)(1)(xiv)", "note": "A CAP becomes effective only upon final Commission acceptance.", "link": "https://www.ecfr.gov/current/title-16/chapter-II/subchapter-B/part-1115#:~:text=An%20acknowledgment%20that%20the%20corrective%20action%20plan%20becomes%20effective%20only,its%20final%20acceptance%20by%20the%20Commission", "link_method": "text", "n": 15}, {"source_id": "S2", "quote": "This handbook was prepared by the CPSC staff, and has not been reviewed or approved by, and may not necessarily reflect the views of, the Commission.", "locator": "Recall Handbook cover disclaimer", "note": "The Handbook is CPSC staff guidance that was not reviewed or approved by the Commission and may not reflect Commission views.", "link": "https://www.cpsc.gov/s3fs-public/RecallHandbookFINAL9_2technicalrevision_3052025.pdf#page=1", "link_method": "page", "n": 16}, {"source_id": "S2", "quote": "Revised August, 2021", "locator": "Recall Handbook, page footer (printed pages 15, 16 and 27)", "note": "The supplied Handbook text visibly identifies its revision as August 2021.", "n": 17}, {"source_id": "S2", "quote": "Identify the location of the potentially unsafe products, and determine how many are at each level of distribution.", "locator": "Recall Handbook § VI.A, printed page 15", "note": "Recall planning should determine product counts and locations at each distribution level.", "link": "https://www.cpsc.gov/s3fs-public/RecallHandbookFINAL9_2technicalrevision_3052025.pdf#page=15", "link_method": "page", "n": 18}, {"source_id": "S2", "quote": "Notify retailers to stop selling the product, and ask them to help identify consumers who own the product.", "locator": "Recall Handbook § VI.A, printed page 15", "note": "Recall planning should include retailer stop-sale notice and retailer assistance identifying product owners.", "link": "https://www.cpsc.gov/s3fs-public/RecallHandbookFINAL9_2technicalrevision_3052025.pdf#page=15", "link_method": "page", "n": 19}, {"source_id": "S2", "quote": "Review existing databases to identify potential product owners, e.g., product registration and customer service records.", "locator": "Recall Handbook § VI.A, printed page 15", "note": "Existing registration and customer-service databases should be reviewed to identify potential product owners.", "link": "https://www.cpsc.gov/s3fs-public/RecallHandbookFINAL9_2technicalrevision_3052025.pdf#page=15", "link_method": "page", "n": 20}, {"source_id": "S2", "quote": "Develop a plan to quarantine and correct returned products.", "locator": "Recall Handbook § VI.A, printed page 15", "note": "Recall execution should include a plan to quarantine and correct returned products.", "link": "https://www.cpsc.gov/s3fs-public/RecallHandbookFINAL9_2technicalrevision_3052025.pdf#page=15", "link_method": "page", "n": 21}, {"source_id": "S2", "quote": "proper control and tracking of all defective materials returned in the recall and to ensure they do not reenter the stream of commerce.", "locator": "Recall Handbook § VI.A, printed page 15", "note": "Returned recalled materials should be controlled and tracked so they do not reenter commerce.", "link": "https://www.cpsc.gov/s3fs-public/RecallHandbookFINAL9_2technicalrevision_3052025.pdf#page=15", "link_method": "page", "n": 22}, {"source_id": "S2", "quote": "Prepare to monitor the product recall, and provide timely progress reports to the CPSC.", "locator": "Recall Handbook § VI.A, printed page 15", "note": "Recall planning should provide for monitoring and timely progress reporting to CPSC.", "link": "https://www.cpsc.gov/s3fs-public/RecallHandbookFINAL9_2technicalrevision_3052025.pdf#page=15", "link_method": "page", "n": 23}, {"source_id": "S2", "quote": "Companies should prepare, for CPSC approval, a comprehensive communications plan, including a media plan utilizing direct notice, for communicating the recall.", "locator": "Recall Handbook § VI.A, printed page 15", "note": "Companies should prepare a comprehensive communications plan, including media and direct notice, for CPSC review.", "link": "https://www.cpsc.gov/s3fs-public/RecallHandbookFINAL9_2technicalrevision_3052025.pdf#page=15", "link_method": "page", "n": 24}, {"source_id": "S2", "quote": "In determining what forms of notice to use, the company should consider how the product was marketed, its user population, the estimated useful life of the product, and how the product is most likely to be maintained and repaired. For targeted notice campaigns, it is most effective to use the same platforms and market segmentation as the company used during sales efforts to announce the recall.", "locator": "Recall Handbook § VI.B, printed page 16", "note": "Notice-channel selection should consider marketing methods, user population, useful life, maintenance and repair patterns, and the platforms and segmentation used for sales.", "link": "https://www.cpsc.gov/s3fs-public/RecallHandbookFINAL9_2technicalrevision_3052025.pdf#page=16", "link_method": "page", "n": 25}, {"source_id": "S2", "quote": "allows CPSC to assess the effectiveness of the company’s recall by evaluating the number of products remedied, the number of consumers notified of the recall, and any post-recall announcement incidents and injuries.", "locator": "Recall Handbook § VIII, printed page 26", "note": "CPSC assesses recall effectiveness using products remedied, consumers notified, and post-announcement incidents and injuries.", "link": "https://www.cpsc.gov/s3fs-public/RecallHandbookFINAL9_2technicalrevision_3052025.pdf#page=26", "link_method": "page", "n": 26}, {"source_id": "S2", "quote": "Verifying disposal or destruction of recalled products. Requests to verify should be submitted in writing and in advance of scheduling the disposal", "locator": "Recall Handbook § VIII, printed page 26", "note": "Verification of disposal or destruction should be coordinated by written advance request before scheduling.", "link": "https://www.cpsc.gov/s3fs-public/RecallHandbookFINAL9_2technicalrevision_3052025.pdf#page=26", "link_method": "page", "n": 27}, {"source_id": "S2", "quote": "the company may submit an updated progress report and request that the CPSC cease monitoring the recall.", "locator": "Recall Handbook § VIII, printed page 26", "note": "A company may request cessation of active CPSC monitoring through an updated progress report.", "link": "https://www.cpsc.gov/s3fs-public/RecallHandbookFINAL9_2technicalrevision_3052025.pdf#page=26", "link_method": "page", "n": 28}, {"source_id": "S2", "quote": "Even after active monitoring has ceased, the company should continue to implement the recall plan until as many products as possible have been removed from the marketplace.", "locator": "Recall Handbook § VIII, printed page 26", "note": "Recall implementation should continue after active monitoring ceases until as many products as possible have been removed from the marketplace.", "link": "https://www.cpsc.gov/s3fs-public/RecallHandbookFINAL9_2technicalrevision_3052025.pdf#page=26", "link_method": "page", "n": 29}, {"source_id": "S2", "quote": "The plan should include written policies and procedures that clearly identify the steps to be taken during and after a recall, and that explain the roles of each employee in the process.", "locator": "Recall Handbook § IX, printed page 27", "note": "A recall execution plan should use written procedures identifying steps and employee roles during and after the recall.", "link": "https://www.cpsc.gov/s3fs-public/RecallHandbookFINAL9_2technicalrevision_3052025.pdf#page=27", "link_method": "page", "n": 30}, {"source_id": "S2", "quote": "Procedures that allow stock keeping units (SKUs) for recalled products to be blocked permanently to prevent employees from overriding SKU blocks;", "locator": "Recall Handbook § IX, printed page 28", "note": "Recall inventory controls should include permanent, non-overridable SKU blocks.", "link": "https://www.cpsc.gov/s3fs-public/RecallHandbookFINAL9_2technicalrevision_3052025.pdf#page=28", "link_method": "page", "n": 31}, {"source_id": "S3", "quote": "STIPULATED MATTER MATERIALS\n\nAurora Trail Goods, Inc. / SolaraGo ET-220 Post-Report Corrective-Action Matter\n\n\n\nRecord status and scope\n\nComplete fictional Aurora ET-220 post-report corrective action plan (CAP) drafting record through the stated cutoff. Stipulated proposals and targets remain proposals; every unresolved staff-dependent item must remain conditional.\n\nAll entities, products, incidents, communications, quantities, dates, and commercial positions identified as fictional below are stipulated solely for this closed matter.\n\n\n\nClosed-record use restrictions\n\n- Do not present any stipulated matter fact as a statement, finding, admission, or position of CPSC or any real person or entity.\n\n- Do not infer facts after the information cutoff or fill an expressly unresolved negotiating item with an invented agreement.\n\n- Do not use this record to reopen the completed reporting decision or to infer a reporting-duty conclusion from the incident chronology.\n\n- Do not treat a company proposal, operational target, or internal control as a legal conclusion or as staff or Commission approval.\n\n\n\nOutside the scope of this engagement\n\n- Whether Aurora had a duty to report under Section 15(b), when any such duty arose, whether the September 4 report was timely or complete, or whether any person violated a reporting obligation.\n\n- Whether the ET-220 legally constitutes a substantial product hazard, whether Aurora admits that status, or whether CPSC has made a preliminary or final hazard determination.\n\n- Whether CPSC should bring an enforcement action, seek a compulsory remedy, impose a civil or criminal penalty, or approve, reject, or require changes to the eventual proposal.\n\n- Product-liability, warranty, insurance-coverage, indemnity, privilege, preservation, employment, tax, and securities-law questions.\n\n- An independent privacy-law analysis or a conclusion that any contact method is lawful beyond the fixed operational permissions and restrictions stipulated in this record.\n\n- Drafting final consumer notices, a press release, social-media copy, retailer posters, call-center scripts, or a Section 15(b) report; those materials may be identified as dependencies or attachments but are not the requested work product.\n\n- Any prediction that the Commission will finally accept a CAP, that staff will agree to a proposed term, or that the matter will close on a particular date.\n\n\n\nInformation cutoff\n\nSeptember 16, 2026, 5:00 p.m. Eastern Time. Treat this time as the closed factual-record cutoff. Do not infer later events, approvals, communications, incidents, sales, returns, or performance.\n\n\n\nStipulated facts\n\nFact 1. Aurora Trail Goods, Inc. (Aurora) is a fictitious Delaware corporation with its principal place of business in Colorado. SolaraGo, TrailHub, CampSquare, MarketSquare, Red Pine Returns, ClearCycle Materials, and every individual, address, product, incident, communication, quantity, date, and commercial position in this record are fictional stipulated facts for this closed matter and do not describe a real person, company, product, recall, or CPSC matter.\n\nFact 2. Aurora submitted a Section 15(b) report concerning the ET-220 to CPSC at 9:12 a.m. Eastern Time on September 4, 2026. Aurora's reporting decision is final for this matter. The parties have directed recall counsel to work only on a proposed voluntary corrective-action-plan term sheet and execution protocol after that report; the basis, timing, sufficiency, and legal necessity of the report are not part of the requested work.\n\nFact 3. The covered product is the SolaraGo Rechargeable Camp Lantern, model ET-220, sold in matte black and blaze orange. The black unit has SKU ET220-BLK and UPC 790000022011; the orange unit has SKU ET220-ORG and UPC 790000022028. The model, SKU, date code, and serial number are printed on a silver label inside the battery-door recess.\n\nFact 4. Covered ET-220 units bear date codes 26015 through 26183 and serial numbers in the format ET22-YYDDD-NNNNN. They were manufactured from January 15 through July 2, 2026, imported from January 28 through July 18, 2026, and sold in the United States from February 12 through September 3, 2026 for advertised prices between $54.99 and $69.99.\n\nFact 5. Aurora imported 82,400 ET-220 units in the covered date-code range. Of those, 79,300 were shipped into distribution and 3,100 remained in Aurora's control when the hold began. Aurora cannot reliably identify a narrower serial-number subset because the contract manufacturer's component-lot map does not link the implicated battery-cell lots to finished-unit serial numbers. Aurora therefore treats all 82,400 units as the affected population for this matter.\n\nFact 6. The 79,300 distributed units were allocated as follows: 21,000 to TrailHub stores and trailhub.com; 12,500 to CampSquare stores and campsquare.com; 8,300 to 140 independent outdoor retailers; 25,600 through Aurora's own website; and 11,900 through MarketSquare's online marketplace and fulfillment network. Sales reached all 50 states and the District of Columbia. Aurora made no sales into Puerto Rico or other U.S. territories.\n\nFact 7. As of the cutoff, Aurora's reconciled location ledger shows 3,100 never-distributed units at Aurora's Colorado warehouse; 2,080 units in TrailHub facilities; 1,140 in CampSquare facilities; 640 reported by independent retailers; 400 in MarketSquare fulfillment centers; and 1,240 complaint or warranty returns already received by Aurora. The 1,240 returns came from the distributed population and are not additional units. Subtracting channel inventory and those returns from the 79,300 distributed units leaves an estimated 73,800 units with consumers or otherwise outside confirmed channel inventory.\n\nFact 8. Aurora has high-resolution photographs of both colors, the interior label, the packaging, and the charging port. The color, SKU, UPC, date code, and serial format distinguish the ET-220 from the earlier ET-210 and the redesigned ET-221. The exterior silhouette alone does not reliably distinguish the three models.\n\nFact 9. Aurora's engineering investigation found that a burr on an internal battery-pack weld can abrade a cell separator after ordinary drops or vibration. The condition can cause internal shorting, overheating, smoke, ignition, and a fire or burn hazard. The lantern may appear and operate normally before the condition manifests.\n\nFact 10. Through the cutoff, Aurora has logged 17 distinct ET-220 overheating or smoke incidents. Five of the 17 involved open flame; three of those five caused reported damage to a tent, a garage shelf, or a vehicle cargo mat. Two consumers reported first-degree burns treated without hospitalization. No death, hospitalization, or other reported injury is in the closed record.\n\nFact 11. The first overheating complaint was received on April 19, 2026; the first open-flame incident was received on May 28; the first reported burn was received on June 17; and Aurora's laboratory reproduced internal shorting on August 21. Sixteen incidents, including both burns, were known when Aurora made the September 4 report. A seventeenth smoke incident with no injury or property damage was received on September 10 and was relayed to the assigned CPSC compliance attorney the same day.\n\nFact 12. Aurora's incident team has adopted an interim business position that ET-220 owners should stop using and charging the lantern, disconnect it from power, and place it away from combustible material pending remedy instructions. A visibly swollen, leaking, unusually hot, smoking, or damaged unit is not to be mailed or transported by the consumer; Aurora's special-handling vendor can arrange local pickup. This position has not yet appeared in a public announcement because no public recall announcement has issued by the cutoff.\n\nFact 13. Aurora's board has authorized the company to propose a consumer election between (a) a full $69.99 refund or (b) a no-cost replacement ET-221 lantern. Aurora has not authorized a coupon, store credit, pro-rated refund, or consumer-installed repair as the consumer remedy. These are Aurora's negotiating and operational positions, not stipulations that CPSC staff has accepted them or that they are legally sufficient.\n\nFact 14. Aurora can verify eligibility from a photograph showing the ET-220 model label and legible serial number. A receipt is not available for many channel sales and Aurora does not intend to require one. If the label is illegible, Aurora's customer-care team can review photographs of the lantern, packaging, charging port, color, and purchase information; disputed eligibility decisions are escalated to the recall program manager rather than denied automatically.\n\nFact 15. The ET-220 battery pack is not consumer-accessible without cutting a sealed enclosure. Aurora's engineering and product-safety teams concluded that a field repair or mailed replacement battery pack cannot be implemented with their existing tools, instructions, or service network. No repair design has completed validation by the cutoff.\n\nFact 16. The ET-221 uses a different battery module, SKU, UPC, and serial prefix. An ISO/IEC 17025-accredited laboratory completed Aurora's specified drop, vibration, charging, and thermal-abuse test protocol on 120 ET-221 samples on September 12 without reproducing the ET-220 failure mode. Aurora has 8,000 ET-221 units available on September 30 and a documented production capacity of 12,000 additional units per week beginning October 5. CPSC staff has received the test report but has not approved the replacement or test protocol.\n\nFact 17. Aurora's payment vendor can issue an electronic refund within three business days after eligibility verification, or mail a check within seven business days if electronic payment is unavailable. The replacement-fulfillment warehouse can ship up to 4,000 ET-221 units per business day. Aurora's proposed service goal is to dispatch the selected remedy within ten business days after eligibility verification, subject to the disclosed replacement-supply ramp.\n\nFact 18. Aurora sent a written stop-sale and inventory-hold notice at 10:05 a.m. Eastern Time on September 4 to TrailHub, CampSquare, MarketSquare, and all 140 independent retailers. The notice identified both SKUs and UPCs, described the fire and burn hazard, directed removal from physical and online sale, required segregation from saleable inventory, and requested inventory and acknowledgment responses by September 6.\n\nFact 19. TrailHub, CampSquare, MarketSquare, and 136 of the 140 independent retailers acknowledged the stop-sale. Four independent retailers, associated with an estimated 118 units within the 640-unit independent-retailer total, have not acknowledged despite two emails and three telephone attempts. Aurora's warehouse hold and ERP block became active on September 4; the two national retailers completed register and online SKU blocks on September 5; and MarketSquare disabled the listing on September 5. No confirmed sale after those controls is in the record.\n\nFact 20. Aurora and each national retailer ran test scans of both affected SKUs on September 6; the transactions were blocked and could not be overridden at the register. Aurora's daily exception report found one internal transfer attempt on September 7, which the ERP block stopped. Independent retailers do not share a common point-of-sale system, and their SKU-block testing remains their responsibility under Aurora's current notice.\n\nFact 21. Aurora's direct-to-consumer sales file contains 25,600 ET-220 orders, with 24,980 deliverable email addresses, 25,310 postal addresses, and 23,700 mobile numbers. Of the mobile numbers, 18,200 have an affirmative text-message consent recorded under Aurora's current customer-contact settings. The records identify SKU, transaction date, and destination but do not prove who currently possesses each unit.\n\nFact 22. Aurora's product-registration database contains 18,420 ET-220 registrations with an email or postal address. Of those registrations, 11,760 match direct-to-consumer orders, leaving 6,660 registrations not already in the direct-sales file. The database records serial number, registration date, and self-reported place of purchase; 510 email addresses and 230 postal addresses in the registration file failed Aurora's most recent validity check.\n\nFact 23. CampSquare can identify 8,400 SKU-specific purchasers through transaction-linked loyalty records and will send Aurora-approved safety communications itself. TrailHub has 13,900 loyalty-member contacts associated with stores and dates in which ET-220 sales occurred, but its data cannot identify which members bought the product. MarketSquare can send platform messages to all 11,900 ET-220 transaction accounts but will not give Aurora raw customer contact data. The independent retailers have no centralized purchaser list. Cross-channel overlap beyond the stated Aurora registration match has not been reconciled.\n\nFact 24. Aurora's privacy officer has approved use of Aurora-held email and postal records for a product-safety communication. Aurora's current internal rule permits text outreach only to the 18,200 numbers with recorded text consent unless the privacy officer approves a different basis after review. Retailer and marketplace contracts require those partners to send messages from their own systems. Recall vendors may receive only the fields needed for their assigned function, may not use the data for marketing, must restrict access to assigned personnel, must log disclosures, and must return or delete the data within 60 days after Aurora closes the applicable campaign. These are stipulated operational constraints, not conclusions about any privacy law.\n\nFact 25. Aurora can export customer and registration records with name, contact field, product identifier, transaction or registration source, and message-delivery status. Its legal and privacy teams can transmit an encrypted export through a CPSC-designated secure channel and can document the fields, source, match logic, and known duplicate limitations. No export has yet been requested or transmitted, and Aurora has not received staff direction on format or cadence.\n\nFact 26. Aurora has reserved the URL solarago.com/ET220 and the toll-free number 1-888-555-0220, but neither is public by the cutoff. Its communications vendor can prepare English and Spanish email, postal, web, retailer, marketplace, social-media, paid-search, and press materials. TrailHub and CampSquare can place in-store notices at all locations that sold the product. Aurora has not released any notice text, launch date, paid-media allocation, or consumer script, and CPSC staff has not approved any communication.\n\nFact 27. Aurora's customer-care vendor can activate 80 trained English- and Spanish-speaking agents within 48 hours and surge to 160 agents within 24 additional hours. At the planned staffing ratio, the vendor forecasts capacity for 9,000 calls and 6,000 web submissions per day during the first week. The vendor can record product identifiers, remedy elections, special-handling requests, failed deliveries, incident reports, and complaint escalations in Aurora's recall case system.\n\nFact 28. Red Pine Returns is under contract to receive ET-220 units at a fenced Colorado facility with capacity for 20,000 quarantined units and intake capacity of 4,000 units per business day. It can scan the serial number, photograph the label and condition, assign a custody identifier, record each custody transfer, segregate damaged batteries, and reconcile the unit to a consumer claim or channel shipment.\n\nFact 29. Aurora's hazardous-materials carrier has 15,000 approved return kits available and can add 10,000 kits per week. Standard ground return service is available in the contiguous states. A separate contractor can perform local pickup in Alaska, Hawaii, and for any visibly damaged, swollen, hot, leaking, or smoking unit; that contractor can begin October 5 and handle 500 pickups per week. Consumers are not expected to package or ship a visibly compromised unit themselves.\n\nFact 30. The 3,100 warehouse units and 1,240 returned units are physically segregated in access-controlled cages, marked 'ET-220 HOLD - NOT FOR SALE,' and blocked from sale, donation, salvage, refurbishment, or ordinary return-to-stock workflows. Red Pine's system rejects an ET-220 serial number from release to saleable inventory. Aurora's internal audit team verified those controls on September 11.\n\nFact 31. Aurora proposes destruction and materials recovery for all returned and channel-held ET-220 units; it does not propose rework, resale, donation, liquidation, or return to the foreign manufacturer. ClearCycle Materials can process 15,000 units per month, keep recalled units separate from other material, issue lot-level weight and unit-count reconciliations, and provide signed certificates identifying the date, quantity, method, operator, and witness. No destruction has occurred, no date has been scheduled, and CPSC staff has not approved a method or indicated whether it wishes to witness or otherwise verify disposition.\n\nFact 32. Aurora has designated its Vice President of Quality as recall program executive, its Product Safety Director as day-to-day program manager, its General Counsel as CPSC liaison, its Supply Chain Director as channel and inventory owner, its Customer Experience Director as hotline and remedy owner, its Data Protection Officer as contact-data owner, and its Controller as budget and payment owner. Red Pine, ClearCycle, the communications vendor, and the customer-care vendor each report to the corresponding Aurora owner; none is authorized to change product scope, remedy terms, public messages, or disposition without written Aurora approval.\n\nFact 33. Aurora has assigned 12 full-time employees to the recall command team for the first 90 days, in addition to the hotline personnel. Channel, warehouse, customer-care, finance, incident-intake, and privacy personnel have draft role-specific procedures. Training can be completed within 48 hours after the procedures and consumer scripts are frozen. Aurora requires completion records and weekly refresher briefings during the first month.\n\nFact 34. Aurora's board authorized an $11.2 million recall reserve: $5.8 million for refunds and replacement inventory; $1.4 million for return transport, quarantine, and disposition; $1.6 million for direct notice, retailer support, and paid media; $1.1 million for hotline, systems, and temporary staffing; and $1.3 million as an unallocated contingency. The Controller may move up to $500,000 among categories; a larger reallocation requires the Chief Financial Officer. The reserve is a planning constraint and is not a cap on action that Aurora later authorizes.\n\nFact 35. Aurora's recall case system can report, by day and cumulatively: affected units; channel units located, held, returned, or destroyed; stop-sale acknowledgments and exceptions; unique direct contacts attempted and delivered by channel; hotline and web contacts; remedy claims by type; eligibility approvals and escalations; refunds issued; replacements shipped; units received and quarantined; custody mismatches; disposition certificates; post-announcement incidents, injuries, and property damage; and estimated spend against budget. The system can show known cross-file duplicates separately rather than treating every message as a unique consumer.\n\nFact 36. Aurora's command team has adopted daily internal dashboards for the first 30 days after announcement, weekly executive reviews for the first 90 days, and monthly data freezes that can support a CPSC progress report. Aurora proposed monthly reports during the September 9 staff conference. Staff said it would evaluate the proposed cadence with the rest of the plan; no reporting schedule or form has been agreed.\n\nFact 37. For internal planning, Aurora set the following targets: 100 percent acknowledgment from known channel accounts before public announcement; reconciliation of at least 99 percent of recorded channel inventory within seven days after announcement; at least 90 percent successful delivery across usable direct email and postal records within 14 days; remedy dispatch within ten business days after verification; zero unauthorized post-hold sales; and custody-ledger variance no greater than one percent at each monthly close. The targets are management proposals, not stipulations of legal sufficiency or staff agreement.\n\nFact 38. Aurora's incident command protocol requires same-day escalation to the program executive and General Counsel for any death, injury requiring medical treatment, open-flame event, confirmed post-hold sale, evidence that a blocked SKU was overridden, or returned unit released from quarantine. It requires escalation within one business day for a channel account that remains unresponsive 48 hours after the applicable deadline, direct-contact delivery below 80 percent for two consecutive days, remedy backlog older than ten business days, custody variance above one percent, replacement-supply slippage longer than seven days, hotline abandonment above 15 percent for two hours, or projected spending above the reserve. Whether and how CPSC staff is notified of an escalated event remains to be addressed in the proposed instrument and subsequent staff discussions.\n\nFact 39. Aurora stopped ET-220 production and canceled open ET-220 purchase orders on September 4. For future lantern production, Aurora has proposed incoming inspection of battery-pack welds, lot-to-serial traceability, supplier process audits, and drop-and-vibration sampling. Those controls are implemented for ET-221 production, but their long-term audit frequency and supplier-remediation milestones have not been agreed with CPSC staff.\n\nFact 40. A CPSC compliance attorney and technical reviewer held an initial conference with Aurora on September 9. Staff asked Aurora to provide a draft term sheet, ET-221 test materials, affected-unit and channel reconciliations, direct-contact capabilities, remedy timing, return and disposition controls, proposed progress fields, and the firm's position on optional non-admission language. Staff did not state that any proposed term was acceptable and did not direct Aurora to use particular language.\n\nFact 41. Aurora agreed to send a negotiation draft to staff by September 18 and proposed September 25 as an announcement target if operational preparations and staff review permit. The dates are planning targets, not agreed deadlines. The company has begun reversible preparation, including data cleansing, vendor reservation, warehouse holds, and training drafts, but has not launched consumer outreach, shipped remedies, published a recall webpage, or issued a public recall announcement.\n\nFact 42. No CAP has been signed by Aurora, finally accepted by the Commission, or otherwise approved as of the cutoff. No staff member has represented that final acceptance is assured. There is no Commission order, consent order, release, closure letter, or agreement limiting later CPSC action in the record. Aurora has authorized counsel to negotiate and revise the proposal but not to represent that a negotiated staff draft is already effective or finally accepted.\n\nFact 43. Aurora's board has elected to request inclusion of the optional non-admission statement described in 16 C.F.R. § 1115.20(a)(1)(xiii), or equivalent language acceptable in the negotiation. Staff has not accepted, rejected, or proposed wording for that request. Aurora has not authorized counsel to make performance of the remedy, monitoring, information-furnishing, or execution commitments conditional on acceptance of the requested statement.\n\nFact 44. The following items are genuinely unresolved at the cutoff and are subjects for negotiation rather than missing records: final notice text and launch sequence; whether staff seeks outreach beyond the available contact populations; final progress-report cadence and format; treatment of the four nonresponsive retailers; verification arrangements for destruction; any changes staff requests to the refund or replacement proposal; and final wording, if any, of the requested non-admission statement.\n\n\n\nExpress assumptions\n\nAssumption A1. Every stipulated fact is an undisputed stipulation for this closed matter unless the statement itself identifies an unresolved item, estimate, proposal, or record limitation.\n\nAssumption A2. The two cited public CPSC sources supply the legal and guidance materials; this record supplies only stipulated matter facts and does not alter, paraphrase, or replace either public source.\n\nAssumption A3. All dates and times are Eastern Time unless another timezone is stated, all dollar figures are U.S. dollars, and stated counts are exact ledger counts except where the text expressly uses 'estimated,' 'forecast,' 'projected,' or another qualifier.\n\nAssumption A4. The affected-population arithmetic uses one 82,400-unit universe. Returned units remain part of the 79,300 distributed-unit population and must not be added again; cross-channel consumer-contact populations may overlap except for the exact registration-to-direct-sale match stated in Fact 22.\n\nAssumption A5. References to staff mean the assigned CPSC compliance attorney, technical reviewer, or other CPSC staff personnel, not the Commission acting as a body. No staff communication in this record is a Commission decision or final acceptance.\n\nAssumption A6. Company positions, budgets, targets, controls, vendor capabilities, and proposed dates are inputs for counsel's work. Their inclusion does not establish that they satisfy any legal or regulatory standard.\n\nAssumption A7. There is no additional CAP, order, agreement, incident file, sales ledger, customer list, staff letter, test result, or approval outside the closed record that may be assumed. A fact identified as unresolved must remain unresolved or be handled conditionally.\n\nAssumption A8. The fixed privacy and vendor-contract restrictions in Fact 24 may be used as operational constraints without conducting a separate federal or state privacy-law analysis.\n", "locator": "Complete stipulated matter record, as of September 16, 2026, 5:00 p.m. Eastern Time", "note": "44 stipulated facts and eight assumptions.", "n": 32}], "sources": [{"id": "S1", "title": "16 CFR Part 1115 - Substantial Product Hazard Reports", "url": "https://www.ecfr.gov/current/title-16/chapter-II/subchapter-B/part-1115", "publisher": "United States Consumer Product Safety Commission and Office of the Federal Register", "doc_type": "eCFR version current through 2026-08-10", "date": "2026-08-10", "synthetic": false}, {"id": "S2", "title": "Product Safety Planning, Reporting, and Recall Handbook", "url": "https://www.cpsc.gov/s3fs-public/RecallHandbookFINAL9_2technicalrevision_3052025.pdf", "publisher": "United States Consumer Product Safety Commission", "doc_type": "Technical revision dated 2025-03-05", "date": "2025-03-05", "synthetic": false}, {"id": "S3", "title": "Aurora ET-220 — fictional matter record", "synthetic": true}], "lineage": {"stages": [{"key": "discovery", "label": "Discovery", "status": "passed"}, {"key": "novelty_check", "label": "Novelty check", "status": "passed"}, {"key": "integration", "label": "Integration", "status": "passed"}, {"key": "difficulty", "label": "Difficulty screen", "status": "passed"}, {"key": "evidence", "label": "Reference analysis", "status": "passed"}, {"key": "reproduction", "label": "Independent reproduction", "status": "returned", "note": "The first independent derivation was incomplete. A subsequent attempt reproduced all eight required results."}, {"key": "comparison", "label": "Comparison", "status": "returned", "note": "The independent answer correctly included all 82,400 units but omitted why a smaller recall was unsupported: the stipulated component-lot map could not identify a narrower subset. A subsequent derivation included this explanation and matched the reference analysis."}, {"key": "family", "label": "Problem family", "status": "passed"}, {"key": "question", "label": "Question & scoring criteria", "status": "passed"}, {"key": "validity", "label": "Validity review", "status": "passed"}, {"key": "consistency", "label": "Consistency review", "status": "returned", "note": "Citing the Recall Handbook by its March 2025 technical-revision label or by its 'Revised August, 2021' footer is now accepted as the same document; only relying on a different edition's content counts as a version error."}, {"key": "polish", "label": "Polish", "status": "passed"}, {"key": "acceptance", "label": "Acceptance", "status": "passed", "note": "Construction and review complete; selected for this public preview."}]}};
